            return None;
        }
    };
    let cuts = match split_plan(text, positions, other_indexes) {
        Ok(cuts) => cuts,
        Err(reason) => {
            tracing::debug!(
                target: "paigasus::anthropic::translate",
                ?reason,
                positions = positions.len(),
                text_bytes = text.len(),
                "anthropic text does not split; one joined block",
            );
            return None;
        }
    };
